import rdflib
from datetime import datetime

g = rdflib.Graph()
g.parse("/app/university_graph.ttl", format="ttl")

ref_date = "2025-08-16"

# For each department, count distinct currently enrolled students
q = """
PREFIX uni: <http://university.org/ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?dept ?student ?enrollDate ?gradDate
WHERE {
    ?student a uni:Person ;
             uni:isEnrolledIn ?course .
    ?course uni:isTaughtIn ?dept .
    OPTIONAL { ?student uni:hasEnrollmentDate ?enrollDate . }
    OPTIONAL { ?student uni:hasGraduationDate ?gradDate . }
}
"""

res = g.query(q)
dept_students = {}
for r in res:
    dept = str(r[0])
    student = str(r[1])
    enrollDate = str(r[2]) if r[2] else None
    gradDate = str(r[3]) if r[3] else None

    # Active if no gradDate or gradDate > ref_date
    is_active = True
    if gradDate and gradDate <= ref_date:
        is_active = False

    if dept not in dept_students:
        dept_students[dept] = {"active": set(), "all": set()}
    dept_students[dept]["all"].add(student)
    if is_active:
        dept_students[dept]["active"].add(student)

for dept, counts in dept_students.items():
    print(f"Dept: {dept}")
    print(f"  Active students: {len(counts[\"active\"])}")
    print(f"  All students: {len(counts[\"all\"])}")
'"}

