import rdflib

g = rdflib.Graph()
g.parse("/app/university_graph.ttl", format="ttl")

q = """
PREFIX uni: <http://university.org/ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?professorName (GROUP_CONCAT(DISTINCT ?country; separator=", ") AS ?countries)
WHERE {
    ?professor a uni:Person ;
               uni:hasName ?professorName ;
               uni:role ?role .

    # 1. Full professor
    FILTER(STRSTARTS(?role, "Professor") && !REGEX(?role, "Assistant|Associate", "i"))

    # 2. Works in at least one dept in EU country
    EXISTS {
        ?professor uni:worksIn ?euDept .
        ?euDept uni:belongsTo ?euUni .
        ?euUni uni:locatedInCountry ?euCountry .
        FILTER(?euCountry IN (
            "AT", "BE", "BG", "CY", "CZ", "DE", "DK", "EE", "ES", "FI", 
            "FR", "GR", "HR", "HU", "IE", "IT", "LT", "LU", "LV", "MT", 
            "NL", "PL", "PT", "RO", "SE", "SI", "SK"
        ))
    }

    # 3. At least one department they work in has > 10 currently enrolled students
    EXISTS {
        ?professor uni:worksIn ?qualDept .
        {
            SELECT ?qualDept
            WHERE {
                ?course uni:isTaughtIn ?qualDept .
                ?student uni:isEnrolledIn ?course .
                OPTIONAL { ?student uni:hasEnrollmentDate ?enrollDate }
                OPTIONAL { ?student uni:hasGraduationDate ?gradDate }
                FILTER(!BOUND(?enrollDate) || ?enrollDate <= "2025-08-16"^^xsd:date)
                FILTER(!BOUND(?gradDate) || ?gradDate > "2025-08-16"^^xsd:date)
            }
            GROUP BY ?qualDept
            HAVING (COUNT(DISTINCT ?student) > 10)
        }
    }

    # Country binding for output
    ?professor uni:worksIn ?workDept .
    ?workDept uni:belongsTo ?workUni .
    ?workUni uni:locatedInCountry ?country .
}
GROUP BY ?professor ?professorName
"""

res = g.query(q)
for r in res:
    print(r)
'"}

